pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numPlays) public {
        // Bound to a reasonable range to allow multiple plays but keep fuzzing fast
        numPlays = bound(numPlays, 1, 20);

        uint256 totalPaidIn = 0;
        bool wonAtLeastOnce = false;

        for (uint256 i = 0; i < numPlays; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(player, 10 ether);
            vm.prank(player);

            try c.play{value: 10}() {
                // Call succeeded
                totalPaidIn += 10;

                // Check if this play resulted in a win by looking for the fee transfer to bank
                // After a win, pot should be 0
                // We can detect a win by checking if pot is 0 immediately after a successful call
                if (c.pot() == 0) {
                    wonAtLeastOnce = true;
                    totalPaidIn = 0; // Pot reset, so running total resets
                }
            } catch {
                // Play reverted (msg.value != 10 or other issue)
                // Nothing changes
            }
        }

        // The property: after any sequence of plays, pot equals the sum of ticket amounts
        // since the last win. If no win occurred, pot = total paid in.
        // If a win occurred, pot was reset to 0 and subsequent plays add to it.
        assertEq(c.pot(), totalPaidIn, "Pot should equal the sum of ticket amounts since last win");
    }
}

