import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 seed1, uint256 seed2) public {
        vm.assume(sender != address(0));
        vm.assume(sender != c.bank());
        // force two play() calls; we need enough ether for both
        vm.deal(sender, 20 ether);

        // set block properties to influence randomness
        vm.roll(uint256(keccak256(abi.encode(seed1))) % 1000 + 1);
        vm.warp(uint256(keccak256(abi.encode(seed2))) % 1000000 + 1);

        vm.startPrank(sender);
        c.play{value: 10}();
        c.play{value: 10}();
        vm.stopPrank();

        // After two plays, the pot must be 0, 10, or >= 20.
        // The mutant will leave pot == 10 when the first play wins (resets to 0) and the second play loses (adds 10 without reset).
        // The reference always ensures pot is 0 or >= 20 (TICKET_AMOUNT + FEE_AMOUNT) after two plays,
        // because a win resets to 0 and a loss accumulates, so after two plays: 0, 10+10=20, or 10+... but never exactly 10.
        uint pot = c.pot();
        assertTrue(pot == 0 || pot == 10 || pot >= 20);
    }
}

